package ui;
import javafx.geometry.Insets; import javafx.scene.control.*; import javafx.scene.layout.*; import java.util.function.BooleanSupplier;
public class SettingsView extends ScrollPane {
 public SettingsView(Runnable toggleTheme,BooleanSupplier dark){VBox body=new VBox(18);body.setPadding(new Insets(26));body.getStyleClass().add("page-content");Label general=caption("GENERAL"),appearance=caption("APPEARANCE"),about=caption("ABOUT");ToggleGroup group=new ToggleGroup();RadioButton light=new RadioButton("Light"),darkButton=new RadioButton("Dark");light.setToggleGroup(group);darkButton.setToggleGroup(group);(dark.getAsBoolean()?darkButton:light).setSelected(true);group.selectedToggleProperty().addListener((o,old,n)->{if(n!=null&&dark.getAsBoolean()!=darkButton.isSelected())toggleTheme.run();});VBox choice=new VBox(7,new Label("Theme"),muted("Choose how Smart Library looks on this device."),light,darkButton);choice.getStyleClass().add("settings-card");body.getChildren().addAll(general,card("Application information","Smart Library Management System keeps your catalog, members and lending workflow together."),appearance,choice,about,card("Smart Library Management System","Native Java 26 · JavaFX 26 · Version 1.0.0"));setContent(body);setFitToWidth(true);setHbarPolicy(ScrollBarPolicy.NEVER);}
 private Label caption(String s){Label l=new Label(s);l.getStyleClass().add("section-caption");return l;} private Label muted(String s){Label l=new Label(s);l.getStyleClass().add("muted-text");return l;} private VBox card(String title,String copy){Label h=new Label(title);h.getStyleClass().add("card-heading");Label p=muted(copy);p.setWrapText(true);VBox b=new VBox(7,h,p);b.getStyleClass().add("settings-card");return b;}
}
